//! Table tests of `Coll.patch` by the JVM class of its receiver and of its patch. A specialised
//! receiver (`CollOverArray$mcB$sp`, `$mcZ$sp`, `$mcI$sp`: a `Coll[Byte]`, a `Coll[Boolean]` and an
//! `indices` result, by their producers) reads `patch.toArray` through its own class, a cast of
//! the patch's ARRAY to its primitive array (v6.0.6 `CollsOverArrays.scala:94-98`), so a patch held
//! over another array is refused though it is empty; a generic receiver hands its builder the
//! patch's items. The rows are sigma-state 6.0.7's at activated version 3 (queue item 31's
//! `measure/`, generated by `measure/tests/gen_rows_test.py`)
use crate::eval::test_util::{eval_body_at, innermost, jvm_text};
use crate::eval::EvalError;
use ergotree_ir::ergo_tree::ErgoTreeVersion;

/// A row: its name in the round's row sets, the expression's bytes, the tree version, what the jars
/// answer, and the cost counter. The answer is the value as `jvm_text` prints it, `CAST` where
/// the jars throw a `ClassCastException` on the patch's array against a primitive array (the
/// refusal a specialised receiver makes before anything is stored: the error is
/// `EvalError::UnexpectedValue`), or `ERR` for any other error
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// The rows whose outcome, value or cost counter is not the table's
fn wrong_rows(rows: &[Row]) -> alloc::vec::Vec<alloc::string::String> {
    let mut wrong = alloc::vec::Vec::new();
    for (name, body, version, expected, cost) in rows {
        let (res, stopped_at) = eval_body_at(body, ErgoTreeVersion::from(*version), 3);
        let as_expected = match (&res, *expected) {
            (Err(_), "ERR") => true,
            (Err(e), "CAST") => matches!(innermost(e), EvalError::UnexpectedValue(_)),
            (Ok(v), text) => jvm_text(v) == text,
            (Err(_), _) => false,
        };
        if !as_expected || stopped_at != *cost {
            wrong.push(alloc::format!(
                "{name}: expected {expected} at {cost}, got {res:?} at {stopped_at}"
            ));
        }
    }
    wrong
}

